insert into public.hinario_regras (id, assunto, texto, pdf_pagina, aplica_violino) values ('HIN-R01', 'Introdução dos hinos', 'A introdução dos hinos deve ser dada até o sinal.', 6, false) on conflict (id) do nothing;
insert into public.hinario_regras (id, assunto, texto, pdf_pagina, aplica_violino) values ('HIN-R02', 'Velocidade', 'Foram colocadas marcações de metrônomo das velocidades mínimas e máximas em todos os hinos (por exemplo: = 60 - 80), que designam os limites dentro dos quais cada hino deve ser entoado, sendo recomendável que o andamento fique na média entre as velocidades mínima e máxima indicadas.', 6, false) on conflict (id) do nothing;
insert into public.hinario_regras (id, assunto, texto, pdf_pagina, aplica_violino) values ('HIN-R03', 'Interpretação', 'A interpretação do hino, no que diz respeito à intensidade do som, andamento e caráter, independentemente da fórmula de compasso, deve ser adequada à inspiração da poesia. Portanto, recomenda-se ao músico tocar o seu instrumento sempre considerando a poesia de cada hino.', 6, false) on conflict (id) do nothing;
insert into public.hinario_regras (id, assunto, texto, pdf_pagina, aplica_violino) values ('HIN-R04', 'Indicação de interpretação', 'Determinados hinos trazem indicação de interpretação logo após a velocidade do metrônomo, a qual tem como finalidade chamar a atenção do músico para uma forma de interpretação mais específica.', 6, false) on conflict (id) do nothing;
insert into public.hinario_regras (id, assunto, texto, pdf_pagina, aplica_violino) values ('HIN-R05', 'Hinos com "Final" após as estrofes', 'Alguns hinos deste hinário (por exemplo, o hino 41) serão executados tocando-se primeiramente todas as estrofes, uma após a outra, e, apenas ao término da última estrofe, tocar-se-á uma só vez a seção denominada "Final" para encerrar o hino.', 6, false) on conflict (id) do nothing;
insert into public.hinario_regras (id, assunto, texto, pdf_pagina, aplica_violino) values ('HIN-R06', 'Como reconhecer o "Final"', 'Esses hinos serão reconhecidos pelo sinal de ritornello já no início da estrofe e pelas casas de ritornello no fim da estrofe, bem como pela indicação de "Final".', 7, false) on conflict (id) do nothing;
insert into public.hinario_regras (id, assunto, texto, pdf_pagina, aplica_violino) values ('HIN-R07', 'Distribuição das vozes', 'Os violinos devem executar a voz do soprano, as violas a voz do tenor e os violoncelos a voz do baixo. Quando houver necessidade e a critério do encarregado de orquestra, alguns violinos poderão ser solicitados a executar a voz do contralto.', 7, true) on conflict (id) do nothing;
insert into public.hinario_regras (id, assunto, texto, pdf_pagina, aplica_violino) values ('HIN-R08', 'Clave do tenor', 'Neste hinário foi introduzida a escrita do tenor na clave de dó na 3a. linha, específica para as violas. O músico deve ter atenção aos sinais de arcada específicos da voz do seu instrumento.', 7, false) on conflict (id) do nothing;
insert into public.hinario_regras (id, assunto, texto, pdf_pagina, aplica_violino) values ('HIN-R09', 'Oitava', 'Adota-se como padrão nos cultos em geral que os violinos toquem uma oitava acima - salvo se, excepcionalmente, o encarregado de orquestra solicitar que se toque como está escrito. As violas e os violoncelos devem sempre tocar como está escrito.', 7, true) on conflict (id) do nothing;
insert into public.hinario_regras (id, assunto, texto, pdf_pagina, aplica_violino) values ('HIN-R10', 'Sinais de arcada', 'Neste hinário foram introduzidos sinais de arcada para as quatro vozes. Quando houver arcada somente sobre a nota do soprano, essa arcada também se aplica ao contralto. Da mesma forma, quando houver arcada somente sobre a nota do tenor, essa arcada também se aplica ao baixo.', 7, true) on conflict (id) do nothing;
